﻿/*
*/
/* ══════════════════════════════════════════════════════
EXTRA ELEGANCE ADDITIONS  v2
══════════════════════════════════════════════════════ */
/* ── Corner card stagger entry animation ── */
@keyframes ccEntry {
from {
opacity: 0;
transform: translateY(22px) scale(.97);
}
to {
opacity: 1;
transform: translateY(0) scale(1);
}
}
.corner-card.reveal.visible {
animation: ccEntry .5s cubic-bezier(.34,1.1,.64,1) both;
}
.corner-card.reveal.visible.d1 {
animation-delay: .07s;
}
.corner-card.reveal.visible.d2 {
animation-delay: .17s;
}
.corner-card.reveal.visible.d3 {
animation-delay: .27s;
}
/* ── Notice board item hover lift ── */
.notice-item {
transition: background .22s ease, color .22s ease, transform .2s cubic-bezier(.34,1.2,.64,1), box-shadow .2s ease;
}
.notice-item:hover {
transform: translateX(4px);
box-shadow: var(--sh-xs);
}
/* ── Tab content area smooth min-height transition ── */
.tab-content-area {
transition: min-height .3s ease;
}
/* ── Stat item icon sparkle on hover ── */
.stat-item::after {
content: '';
position: absolute;
inset: 0;
border-radius: var(--r-md);
background: rgba(255,255,255,.06);
opacity: 0;
transition: opacity .2s ease;
pointer-events: none;
}
.stat-item:hover::after {
opacity: 1;
}
/* ── QAB banner: animated pulse ring on the emoji icon ── */
.qab-title::before {
animation: qabPulse 2.4s ease-in-out infinite;
}
@keyframes qabPulse {
0%, 100% {
opacity: 1;
}
50% {
opacity: .6;
}
}
/* ── Ticker bar: subtle gradient border ── */
.ticker-bar {
border-left-width: 4px;
border-image: linear-gradient(180deg, var(--col-primary) 0%, var(--col-accent) 100%) 1;
}
/* ── Scroll arrows: smoother appear ── */
.cc-scroll-arrow {
transition: opacity .25s ease, background .2s ease;
}
/* ── Tab btn: active scale down on press ── */
.tab-btn:active {
transform: scale(.96);
}
/* ── Notice card header: subtle animated border ── */
.notice-card-header {
padding: 12px 16px;
border-bottom: 1px solid var(--col-border);
display: flex;
align-items: center;
justify-content: space-between;
/* FIXED: Uses dynamic theme variable for the solid background */
background: var(--col-primary);
color: #fff;
transition: background 0.4s var(--ease);
}
.notice-card-header::after {
content: '';
position: absolute;
bottom: 0;
left: -100%;
width: 60%;
height: 2px;
background: rgba(255,255,255,.4);
animation: noticeHeaderShimmer 3s ease-in-out infinite;
}
@keyframes noticeHeaderShimmer {
0% {
left: -60%;
}
100% {
left: 140%;
}
}
/* ── Dark theme: corner card header tints ── */
body[data-theme="dark"] .cc-red .cc-header {
background: linear-gradient(135deg, rgba(220,38,38,.12) 0%, transparent 70%);
}
body[data-theme="dark"] .cc-blue .cc-header {
background: linear-gradient(135deg, rgba(37,99,235,.12) 0%, transparent 70%);
}
body[data-theme="dark"] .cc-green .cc-header {
background: linear-gradient(135deg, rgba(22,163,74,.12) 0%, transparent 70%);
}
/* ── Pill sub-label (class range) ── */
.pp-sub {
font-size: .74em;
font-weight: 500;
opacity: .72;
display: inline;
white-space: nowrap;
}
.pp-btn.pp-active .pp-sub {
opacity: .9;
}
/* ══════════════════════════════════════════════
SCROLL TO TOP (Circular SVG Progress)
══════════════════════════════════════════════ */
