/* ══════════════════════════════════════════════
LAST DATES GRID (Ultra-Premium / Modern Soft)
══════════════════════════════════════════════ */
.last-dates-grid {
display: grid;
grid-template-columns: repeat(auto-fill, minmax(310px, 1fr));
gap: 22px;
padding: 16px 8px;
}
.ld-card {
background: #ffffff;
/* Extra rounded corners for a modern app feel */
border-radius: 20px;
padding: 28px 24px 24px;
display: flex;
flex-direction: column;
/* Barely visible border, massive ultra-soft shadow */
border: 1px solid rgba(226, 232, 240, 0.4);
box-shadow: 0 10px 40px -10px rgba(15, 23, 42, 0.06), 0 2px 10px -2px rgba(15, 23, 42, 0.02);
transition: transform 0.5s cubic-bezier(0.2, 0.8, 0.2, 1), box-shadow 0.5s ease, border-color 0.5s ease;
position: relative;
overflow: hidden;
z-index: 1;
}
/* Float up and cast a deeper, blue-tinted glow on hover */
.ld-card:hover {
transform: translateY(-8px);
box-shadow: 0 20px 50px -12px rgba(26, 58, 139, 0.15);
border-color: rgba(26, 58, 139, 0.1);
}
/* Sleek top accent line instead of a side border */
.ld-card::before {
content: '';
position: absolute;
top: 0;
left: 0;
right: 0;
height: 4px;
/* Beautiful 3-color gradient */
background: linear-gradient(90deg, #1A3A8B 0%, #3B82F6 50%, #10B981 100%);
opacity: 0.85;
transition: height 0.4s ease, opacity 0.4s ease;
}
.ld-card:hover::before {
height: 6px;
opacity: 1;
}
/* Premium watermark icon in the background (using FontAwesome) */
.ld-card::after {
content: '\f19d'; /* FontAwesome Graduation Cap */
font-family: 'Font Awesome 6 Free';
font-weight: 900;
position: absolute;
bottom: -20px;
right: -20px;
font-size: 130px;
color: rgba(26, 58, 139, 0.025); /* Extremely faint */
transform: rotate(-15deg);
z-index: -1;
transition: all 0.6s cubic-bezier(0.2, 0.8, 0.2, 1);
pointer-events: none;
}
/* Watermark slowly rotates and sharpens on hover */
.ld-card:hover::after {
color: rgba(26, 58, 139, 0.05);
transform: rotate(0deg) scale(1.05);
}
/* Typography Refinements for Premium Look */
.ld-card-main-title {
font-family: var(--ff-head);
font-size: 1.15rem;
font-weight: 800;
color: #0F172A; /* Deep slate, almost black */
margin-bottom: 10px;
letter-spacing: -0.3px;
}
.ld-card-sub {
font-size: 0.88rem;
color: #64748B;
line-height: 1.6;
flex-grow: 1;
margin-bottom: 24px;
}
.ld-card-sub strong {
color: #1E293B;
/*font-weight: 700;*/
}
/* ── Dark Theme Overrides ── */
body[data-theme="dark"] .ld-card {
background: #111827;
border-color: rgba(51, 65, 85, 0.4);
box-shadow: 0 10px 40px -10px rgba(0,0,0,0.5);
}
body[data-theme="dark"] .ld-card:hover {
box-shadow: 0 20px 50px -12px rgba(96, 165, 250, 0.2);
border-color: rgba(96, 165, 250, 0.25);
}
body[data-theme="dark"] .ld-card::after {
color: rgba(255, 255, 255, 0.02);
}
body[data-theme="dark"] .ld-card:hover::after {
color: rgba(255, 255, 255, 0.04);
}
/* ── Premium Soft Pill Badges for Days Left ── */
.ld-days-box {
display: inline-flex;
align-items: center;
padding: 6px 14px;
border-radius: 999px; /* Perfect pill shape */
font-family: var(--ff-head);
font-size: 0.78rem;
font-weight: 800;
letter-spacing: 0.8px;
text-transform: uppercase;
box-shadow: 0 4px 12px -4px rgba(0,0,0,0.05); /* Very soft drop shadow */
transition: transform 0.3s ease, box-shadow 0.3s ease;
}
/* Make the box lift up slightly when you hover over the whole card */
.ld-card:hover .ld-days-box {
transform: translateY(-2px);
box-shadow: 0 8px 16px -4px rgba(0,0,0,0.08);
}
/* Fade the icon slightly to create a premium dual-tone effect */
.ld-days-box i {
opacity: 0.75;
font-size: 0.95rem;
margin-right: 6px;
}
/* Dark Theme Overrides */
body[data-theme="dark"] .ld-days-box {
box-shadow: none;
filter: brightness(0.85) contrast(1.2); /* Adjusts the pastels for dark mode */
}
/* Mobile Adjustments for Grid */
@media (max-width: 768px) {
.last-dates-grid {
grid-template-columns: 1fr;
}
}
/* --- Custom Cursor --- */
.cursor-dot, .cursor-outline {
position: fixed;
top: 0;
left: 0;
transform: translate(-50%, -50%);
border-radius: 50%;
z-index: 99999;
pointer-events: none; /* Lets you click through it */
}
.cursor-dot {
width: 8px;
height: 8px;
background-color: var(--col-primary); /* Uses your theme color */
}
.cursor-outline {
width: 34px;
height: 34px;
border: 2px solid rgba(26, 58, 139, 0.4);
/* Smooth trailing transition */
transition: left 0.1s ease-out, top 0.1s ease-out, width 0.2s, height 0.2s;
}
/* Enlarge on clickable elements */
a:hover ~ .cursor-outline, button:hover ~ .cursor-outline {
width: 50px;
height: 50px;
background-color: rgba(26, 58, 139, 0.05);
}
/* Hide on mobile/tablets */
@media (max-width: 991px) {
.cursor-dot, .cursor-outline {
display: none !important;
}
}
/* --- Process Timeline Redesign --- */
.process-block {
background: var(--col-card);
border: 1px solid var(--col-border);
border-radius: var(--r-md);
padding: 24px;
box-shadow: 0 2px 8px rgba(0,0,0,0.03);
}
.process-block.mt-3 {
margin-top: 20px;
}
.process-block-title {
font-family: var(--ff-head);
font-size: 1.15rem;
font-weight: 700;
color: var(--col-primary);
margin-bottom: 24px;
display: flex;
align-items: center;
gap: 10px;
}
.process-timeline {
display: flex;
flex-direction: column;
gap: 16px;
position: relative;
padding-left: 24px;
border-left: 2px dashed var(--col-border);
margin-left: 12px;
}
.timeline-step {
display: flex;
align-items: center;
position: relative;
}
.step-number {
width: 32px;
height: 32px;
background: #EBF0FB; /* Light blue */
color: #1A3A8B; /* Primary blue */
border-radius: 50%;
display: flex;
align-items: center;
justify-content: center;
font-weight: 800;
font-size: 0.9rem;
position: absolute;
left: -41px; /* Aligns precisely over the dashed border */
top: 50%;
transform: translateY(-50%);
box-shadow: 0 0 0 6px var(--col-card); /* Creates the "cutout" effect over the border */
}
body[data-theme="dark"] .step-number {
background: #1E3A5F;
color: #60A5FA;
box-shadow: 0 0 0 6px #1E293B;
}
.step-content {
background: var(--col-bg);
padding: 12px 16px;
border-radius: var(--r-sm);
width: 100%;
border: 1px solid transparent;
font-size: 0.88rem;
color: var(--col-text);
transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1), border-color 0.3s ease, box-shadow 0.3s ease;
}
.step-content:hover {
transform: translateX(6px);
border-color: rgba(26, 58, 139, 0.3);
background: var(--col-card);
box-shadow: var(--sh-xs);
}
/* ══════════════════════════════════════════════
EXTERNAL LINK (TARGET BLANK) HOVER ARROWS
══════════════════════════════════════════════ */
/* Ensures the absolute position of the arrow stays inside the button/link */
a[target="_blank"] {
position: relative;
}
/* Base configuration for the arrow icon */
a[target="_blank"]::after {
content: '\f08e'; /* FontAwesome 'up-right-from-square' icon */
font-family: 'Font Awesome 7 Pro', 'Font Awesome 6 Pro', 'FontAwesome'; /* Updated for Pro Versions */
font-weight: 900; /* Pro Solid. Use 400 for Regular, or 300 for Light */
font-size: 0.85em;
opacity: 0;
pointer-events: none; /* Prevents the icon from blocking clicks */
transition: opacity 0.3s ease, transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}
/* 1. Applicant Corner & Department Corner Links */
.info-link-item a[target="_blank"] {
padding-right: 32px; /* Make space for the arrow so text doesn't overlap */
}
.info-link-item a[target="_blank"]::after {
position: absolute;
right: 14px;
top: 50%;
transform: translate(-8px, -20%); /* Start slightly down and left */
color: var(--col-primary);
}
.info-link-item a[target="_blank"]:hover::after {
opacity: 1;
transform: translate(0, -50%); /* Slide smoothly to center right */
}
/* 2. Quick Apply Banner Buttons */
.qab-btn[target="_blank"] {
padding-right: 34px;
}
.qab-btn[target="_blank"]::after {
position: absolute;
right: 16px;
top: 50%;
transform: translate(-6px, -20%);
}
.qab-btn[target="_blank"]:hover::after {
opacity: 1;
transform: translate(0, -50%);
}
/* 3. Notice Board & Ticker Links (Inline Text layout) */
.notice-item a[target="_blank"],
.ticker-inner a[target="_blank"] {
display: inline-block;
padding-right: 20px;
}
.notice-item a[target="_blank"]::after,
.ticker-inner a[target="_blank"]::after {
position: absolute;
right: 0;
top: 50%;
transform: translate(-6px, -20%);
color: var(--col-primary);
}
.notice-item a[target="_blank"]:hover::after,
.ticker-inner a[target="_blank"]:hover::after {
opacity: 1;
transform: translate(0, -50%);
}
/* --- Dark Theme Overrides --- */
body[data-theme="dark"] .info-link-item a[target="_blank"]::after,
body[data-theme="dark"] .notice-item a[target="_blank"]::after,
body[data-theme="dark"] .ticker-inner a[target="_blank"]::after {
color: var(--col-accent); /* Brighter blue for dark mode */
}
/* ══════════════════════════════════════════════
1. ADVANCED GLASSMORPHISM & NOISE TEXTURE
══════════════════════════════════════════════ */
:root {
/* Generates a mathematical SVG noise texture pattern */
--noise-bg: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E");
}
/*.top-bar, .stats-bar {
position: relative;
}*/
/* Layer the noise texture over the glassmorphism bars */
.top-bar::after, .stats-bar::after {
content: '';
position: absolute;
inset: 0;
background: var(--noise-bg);
opacity: 0.035; /* Extremely subtle film-grain texture */
mix-blend-mode: overlay;
pointer-events: none;
z-index: 0;
}
.top-bar-inner, .stat-item {
position: relative;
/*z-index: 1;*/ /* Keep text above the noise */
}
/* ══════════════════════════════════════════════
2. DYNAMIC SPOTLIGHT EFFECT (Cards & Blocks)
══════════════════════════════════════════════ */
.spotlight-card {
position: relative;
overflow: hidden;
}
/* Elevate card contents so the spotlight slides underneath them */
.spotlight-card > * {
position: relative;
z-index: 2;
}
/* The invisible spotlight light source */
.spotlight-card::before {
content: '';
position: absolute;
inset: 0;
/* Uses CSS variables updated by Javascript */
background: radial-gradient( 600px circle at var(--mouse-x, 0) var(--mouse-y, 0), rgba(255, 255, 255, 0.35), transparent 40% );
z-index: 1;
pointer-events: none;
opacity: 0;
transition: opacity 0.5s ease;
}
.spotlight-card:hover::before {
opacity: 1;
}
body[data-theme="dark"] .spotlight-card::before {
background: radial-gradient( 600px circle at var(--mouse-x, 0) var(--mouse-y, 0), rgba(255, 255, 255, 0.08), transparent 40% );
}
/* ══════════════════════════════════════════════
3. STAGGERED CASCADE TAB ANIMATIONS
══════════════════════════════════════════════ */
.tab-pane.active .ld-card,
.tab-pane.active .ssp-acc-item,
.tab-pane.active .timeline-step {
animation: cascadeFadeUp 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards;
opacity: 0;
transform: translateY(20px);
}
@keyframes cascadeFadeUp {
to {
opacity: 1;
transform: translateY(0);
}
}
/* Stagger the delay mathematically for a fluid wave effect */
.tab-pane.active .ld-card:nth-child(1), .tab-pane.active .ssp-acc-item:nth-child(1), .tab-pane.active .timeline-step:nth-child(1) {
animation-delay: 0.05s;
}
.tab-pane.active .ld-card:nth-child(2), .tab-pane.active .ssp-acc-item:nth-child(2), .tab-pane.active .timeline-step:nth-child(2) {
animation-delay: 0.10s;
}
.tab-pane.active .ld-card:nth-child(3), .tab-pane.active .ssp-acc-item:nth-child(3), .tab-pane.active .timeline-step:nth-child(3) {
animation-delay: 0.15s;
}
.tab-pane.active .ld-card:nth-child(4), .tab-pane.active .ssp-acc-item:nth-child(4), .tab-pane.active .timeline-step:nth-child(4) {
animation-delay: 0.20s;
}
.tab-pane.active .ld-card:nth-child(5), .tab-pane.active .ssp-acc-item:nth-child(5), .tab-pane.active .timeline-step:nth-child(5) {
animation-delay: 0.25s;
}
.tab-pane.active .ld-card:nth-child(n+6), .tab-pane.active .ssp-acc-item:nth-child(n+6), .tab-pane.active .timeline-step:nth-child(n+6) {
animation-delay: 0.30s;
}
/* ══════════════════════════════════════════════
4. SLEEK SKELETON LOADER (For Eligibility Modal)
══════════════════════════════════════════════ */
.skeleton-loader {
display: flex;
flex-direction: column;
gap: 12px;
padding: 10px 4px;
}
.skeleton-row {
height: 18px;
background: linear-gradient(90deg, #F1F5F9 25%, #E2E8F0 50%, #F1F5F9 75%);
background-size: 200% 100%;
animation: skeletonPulse 1.5s infinite linear;
border-radius: 6px;
}
.skeleton-row.pill {
width: 35%;
height: 26px;
border-radius: 999px;
margin-bottom: 6px;
}
.skeleton-row.long {
width: 95%;
}
.skeleton-row.med {
width: 75%;
}
@keyframes skeletonPulse {
0% {
background-position: 200% 0;
}
100% {
background-position: -200% 0;
}
}
body[data-theme="dark"] .skeleton-row {
background: linear-gradient(90deg, #1E293B 25%, #334155 50%, #1E293B 75%);
}
/* ══════════════════════════════════════════════
1. CAROUSEL MOBILE NUMBERS OVERRIDE FIX
══════════════════════════════════════════════ */
