/* ══════════════════════════════════════════════
GEN-Z UX ENHANCEMENT LAYER
══════════════════════════════════════════════ */
/* ── Reusable CSS utility animation classes ──
Drop any of these onto a future element's class list. */
.anim-fade-up {
animation: gzFadeUp .5s var(--ease) both;
}
.anim-pop {
animation: gzPopIn .4s cubic-bezier(.34,1.56,.64,1) both;
}
.press-scale {
transition: transform .15s var(--ease);
}
.press-scale:active {
transform: scale(.94);
}
.hover-lift {
transition: transform .25s var(--ease), box-shadow .25s var(--ease);
}
.hover-lift:hover {
transform: translateY(-4px);
box-shadow: var(--sh-md);
}
@keyframes gzFadeUp {
from {
opacity: 0;
transform: translateY(16px);
}
to {
opacity: 1;
transform: translateY(0);
}
}
@keyframes gzPopIn {
from {
opacity: 0;
transform: scale(.85);
}
to {
opacity: 1;
transform: scale(1);
}
}
/* ── Magnetic CTA Buttons (qab-btn = your quick-apply "Create Account" /
"Student Login" pills). JS in Main.Master drives the pull + the
cursor-tracked glow via --mx/--my. Desktop/mouse only — see §2c. ── */
.qab-btn {
will-change: transform;
}
.qab-btn-primary::after {
content: '';
position: absolute;
inset: 0;
border-radius: inherit;
background: radial-gradient(circle at var(--mx, 50%) var(--my, 50%), rgba(139,26,26,.18), transparent 60%);
opacity: 0;
transition: opacity .3s ease;
z-index: -1;
pointer-events: none;
}
.qab-btn-primary:hover::after {
opacity: 1;
}
/* ── Liquid Tab Transition — adds a squash/stretch overshoot to the
sliding pill you already have (.tab-nav-bar::after) while it travels
between tabs. JS toggles .liquid-squish on tab change — see §2d. ── */
@keyframes liquidSquish {
0% {
transform: scaleX(1);
}
35% {
transform: scaleX(1.14);
}
65% {
transform: scaleX(0.94);
}
100% {
transform: scaleX(1);
}
}
.tab-nav-bar.liquid-squish::after {
animation: liquidSquish .42s var(--ease) both;
transform-origin: center;
}
/* ── Staggered Card Entrances — extends the existing corner-card
cascade pattern (reuses your ccEntry keyframe) to the helpline grid,
which currently has no stagger. No markup/C# change needed — each
.helpline-card already ships with its own .reveal class from
BuildHelplineHtml(). ── */
.helpline-grid .helpline-card.reveal.visible {
animation: ccEntry .5s cubic-bezier(.34,1.1,.64,1) both;
}
.helpline-grid .helpline-card:nth-child(1).reveal.visible {
animation-delay: .04s;
}
.helpline-grid .helpline-card:nth-child(2).reveal.visible {
animation-delay: .10s;
}
.helpline-grid .helpline-card:nth-child(3).reveal.visible {
animation-delay: .16s;
}
.helpline-grid .helpline-card:nth-child(4).reveal.visible {
animation-delay: .22s;
}
.helpline-grid .helpline-card:nth-child(5).reveal.visible {
animation-delay: .28s;
}
.helpline-grid .helpline-card:nth-child(6).reveal.visible {
animation-delay: .34s;
}
.helpline-grid .helpline-card:nth-child(7).reveal.visible {
animation-delay: .40s;
}
/* ── High Thumb Usability — bumps small circular icon buttons up to
the 44×44px minimum touch target on real touch devices only (mouse
users on desktop keep the current compact sizing). ── */
@media (hover: none) and (pointer: coarse) {
.theme-toggle-btn,
.elig-modal-close,
.jump-nav-toggle,
.ticker-ctrl-btn {
min-width: 44px;
min-height: 44px;
}
.font-ctrl-btn {
min-height: 40px;
padding: 8px 12px;
}
.qab-btn,
.tab-btn,
.pp-btn {
min-height: 44px;
}
}
/* ── No Layout Overlapping — the expanded Jump-to-Contents menu
(.jump-nav.active) can grow tall enough on short mobile viewports to
sit visually on top of the fixed Scroll-to-Top button. JS toggles
body.jump-nav-open — see §2e — so we hide the FAB while the menu is
open instead of letting them collide. ── */
body.jump-nav-open .scroll-to-top-wrap {
opacity: 0;
visibility: hidden;
pointer-events: none;
}
/* ── Smooth Fluid Performance — respect reduced-motion users, and cap
animation cost across the new + existing motion in this file. ── */
@media (prefers-reduced-motion: reduce) {
*, *::before, *::after {
animation-duration: .001ms !important;
animation-iteration-count: 1 !important;
transition-duration: .001ms !important;
scroll-behavior: auto !important;
}
.ticker-inner, .footer-logos-scroll {
animation: none !important;
}
}
/* Make stats cards show a pointer finger when hovered */
.custom-scroll-link {
cursor: pointer;
}
/* ══════════════════════════════════════════════════════
