/* ══════════════════════════════════════════════
SETTINGS GEAR DROPDOWN (Accessibility & Theme)
══════════════════════════════════════════════ */
.settings-dropdown {
position: relative;
}
.settings-menu {
position: absolute;
top: calc(100% + 12px);
right: 0;
background: linear-gradient(135deg, var(--col-primary) 0%, var(--col-primary-d) 100%);
border: 1px solid rgba(255,255,255,0.15);
border-radius: var(--r-md);
