padding: 18px;
display: flex;
flex-direction: column;
gap: 18px;
min-width: 220px;
max-width: calc(100vw - 20px); /* Prevents overflow on tiny phones */
opacity: 0;
visibility: hidden;
transform: translateY(-10px);
transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
z-index: 1060;
}
/* Show State triggered by JS */
.settings-dropdown.active .settings-menu {
opacity: 1;
visibility: visible;
transform: translateY(0);
}
.settings-menu-item {
display: flex;
flex-direction: column;
gap: 10px;
}
.settings-label {
