/* ══════════════════════════════════════════════════════
QUICK ACTION GRID (Bento Box Design)
══════════════════════════════════════════════════════ */
.quick-action-grid {
display: grid;
grid-template-columns: repeat(3, 1fr);
gap: 20px;
