overflow: hidden;
}
/* 1. Primary Card (Create Account) */
.qa-card-primary {
background: linear-gradient(135deg, var(--col-primary) 0%, var(--col-primary-d) 100%);
box-shadow: 0 10px 25px rgba(0, 0, 0, 0.15);
