color: #ffffff;
}
.qa-card-primary .qa-title {
color: #ffffff;
}
.qa-card-primary .qa-subtitle {
color: rgba(255, 255, 255, 0.75);
}
.qa-card-primary .qa-arrow-box {
background: #ffffff;
color: var(--col-primary);
}
/* 2. Outline Cards (Logins) */
.qa-card-outline {
background: #ffffff;
border: 1px solid rgba(226, 232, 240, 0.8);
box-shadow: 0 4px 15px rgba(0, 0, 0, 0.03);
}
.qa-card-outline:hover {
transform: translateY(-6px);
box-shadow: 0 12px 30px rgba(0, 0, 0, 0.08);
border-color: var(--col-primary);
}
.qa-card-outline .qa-icon-box {
background: rgba(0, 0, 0, 0.04);
color: var(--col-primary);
}
.qa-card-outline:hover .qa-icon-box {
background: var(--col-primary);
color: #ffffff;
}
.qa-card-outline .qa-title {
color: var(--col-head);
}
.qa-card-outline .qa-subtitle {
color: var(--col-muted);
}
.qa-card-outline .qa-arrow-box {
background: rgba(0, 0, 0, 0.04);
color: var(--col-muted);
}
.qa-card-outline:hover .qa-arrow-box {
background: var(--col-primary);
color: #ffffff;
}
/* Shared Internal Elements */
.qa-icon-box {
width: 54px;
height: 54px;
border-radius: 14px;
display: flex;
align-items: center;
justify-content: center;
font-size: 1.4rem;
flex-shrink: 0;
margin-right: 16px;
