    .skip-link:focus {
        left: 10px;
        top: 10px;
        width: auto;
        height: auto
    }

/* ══════════════════════════════════════════════
   TOP UTILITY BAR
══════════════════════════════════════════════ */
.top-bar {
    background: var(--col-primary);
    background-image: linear-gradient(135deg,var(--col-primary) 0%,var(--col-primary-d) 100%);
    position: sticky;
    top: 0;
    /*z-index: 1050;*/
