/* ── TICKER — FIX 2: pause/play + drag-scroll ── */
.ticker-bar {
    background: var(--col-card);
    border-left: 5px solid var(--col-accent);
    border-radius: var(--r-sm);
    box-shadow: var(--sh-xs);
    padding: 9px 14px;
    margin: 0 auto;
    max-width: 1230px;
    display: flex;
    align-items: center;
    gap: 10px;
    overflow: hidden;
    transition: background .4s var(--ease);
}

/* The marquee track — becomes a draggable strip when paused */
.ticker-track-wrap {
    flex: 1;
    overflow: hidden;
    position: relative;
    cursor: default;
    min-width: 0;
}

    .ticker-track-wrap.draggable {
        overflow-x: auto;
        cursor: grab;
        scrollbar-width: none;
    }

        .ticker-track-wrap.draggable::-webkit-scrollbar {
            display: none;
        }

    .ticker-track-wrap.dragging {
        cursor: grabbing;
    }

.ticker-inner {
    display: flex;
    align-items: center;
    white-space: nowrap;
    animation: tickerSlideFluid 28s linear infinite;
    color: var(--col-text);
    font-size: .85rem;
    font-weight: 500;
    width: max-content;
    will-change: transform;
}

    .ticker-inner.paused {
        animation-play-state: paused;
    }

.ticker-seg {
    display: inline-flex;
    align-items: center;
    padding-right: 64px; /* gap before the looped copy repeats */
    flex-shrink: 0;
}

@keyframes tickerSlideFluid {
    from {
        transform: translateX(0);
    }

    to {
        transform: translateX(-50%);
    }
}

/* Ticker pause button */
.ticker-ctrl-btn {
    background: linear-gradient(135deg, #152f79 0%, #dc2626 100%); /*var(--col-primary);
*/
    border: none;
    color: #fff;
    border-radius: var(--r-pill);
    width: 26px;
    height: 26px;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    font-size: .7rem;
    flex-shrink: 0;
    transition: var(--tr);
    padding: 0;
}

    .ticker-ctrl-btn:hover {
        background: var(--col-primary-d);
    }

/* ── STATS BAR — redesigned with animated card tiles ── */
/* ── STATS BAR — Individual Floating Cards Design ── */
.stats-bar {
    background: transparent !important; /* Removes the old single-bar background */
    box-shadow: none !important;
    border: none !important;
    max-width: 1400px;
    margin: 0 auto;
    padding: 10px 0 !important;
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 24px;
}

    /* Hide old shimmer effects */
    .stats-bar::before, .stats-bar::after {
        display: none !important;
    }

/* The new individual cards */
.stat-item {
    background: var(--col-card);
    border-radius: 16px;
    padding: 28px 20px;
    text-align: center;
    box-shadow: 0 4px 15px rgba(0,0,0,0.04);
    border: 1px solid var(--col-border);
    border-bottom: 4px solid var(--col-primary); /* Distinctive colored bottom lip */
    transition: transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.4s ease;
    position: relative;
    overflow: hidden;
    z-index: 1;
}

    /* Remove old vertical dividers */
    .stat-item + .stat-item::before {
        display: none !important;
    }

    .stat-item:hover {
        transform: translateY(-8px);
        box-shadow: 0 15px 35px -5px rgba(26, 58, 139, 0.15);
    }

    /* Giant Watermark Icons for each card */
    .stat-item::after {
        font-family: 'Font Awesome 7 Pro', 'Font Awesome 6 Pro', 'FontAwesome';
        font-weight: 900;
        position: absolute;
        right: -10px;
        bottom: -15px;
        font-size: 80px;
        color: rgba(26, 58, 139, 0.04);
        z-index: -1;
        transition: transform 0.5s ease, color 0.5s ease;
        pointer-events: none;
    }

    .stat-item:nth-child(1)::after {
        content: '\f501';
    }
    /* Student Icon */
    .stat-item:nth-child(2)::after {
        content: '\f19c';
    }
    /* University/Dept Icon */
    .stat-item:nth-child(3)::after {
        content: '\f0ae';
    }
    /* Schemes/Tasks Icon */

    .stat-item:hover::after {
        transform: scale(1.15) rotate(-5deg);
        color: rgba(26, 58, 139, 0.08);
    }

.stat-number {
    font-family: var(--ff-head);
    font-size: 2.2rem;
    font-weight: 800;
    color: var(--col-primary); /* Bold colorful text instead of white */
    line-height: 1;
    margin-bottom: 8px;
    text-shadow: none;
    transition: transform 0.2s var(--ease);
}

.stat-item:hover .stat-number {
    transform: scale(1.05);
}

.stat-label {
    font-size: 0.8rem;
    color: var(--col-text);
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

/* Mobile Adjustments */
@media(max-width:768px) {
    .stats-bar {
        grid-template-columns: 1fr 1fr; /* Keep 2 columns */
        gap: 12px;
        margin-left: 12px;
        margin-right: 12px;
        padding: 16px 12px !important;
    }

    /* Forces the 3rd odd item to span the full width cleanly */
    .stat-item:last-child:nth-child(odd) {
        grid-column: 1 / -1;
    }

    .stat-item:nth-child(3)::before {
        display: none !important;
    }

    .stat-number {
        font-size: 1.5rem;
    }
}

