/* ── NOTICE BOARD FIX 4/5: reliable pause/play + drag when paused ── */
.notice-viewport {
    height: 320px;
    overflow: hidden;
    position: relative;
    padding: 8px;
    mask-image: linear-gradient(to bottom,transparent 0%,black 7%,black 93%,transparent 100%);
    -webkit-mask-image: linear-gradient(to bottom,transparent 0%,black 7%,black 93%,transparent 100%);
}

    /* Draggable state when notice is paused — switch to scroll container */
    .notice-viewport.nb-draggable {
        overflow-y: auto;
        overflow-x: hidden;
        scrollbar-width: none;
        -ms-overflow-style: none;
        cursor: grab;
        touch-action: pan-y;
        /* Disable mask so edges are readable */
        mask-image: none;
        -webkit-mask-image: none;
    }

        .notice-viewport.nb-draggable::-webkit-scrollbar {
            display: none;
        }

    .notice-viewport.nb-dragging {
        cursor: grabbing;
    }

.notice-scroll {
    position: absolute;
    width: calc(100% - 16px);
    animation: noticeUp 40s linear infinite;
    /* When draggable, position:relative so natural scroll height works */
}

/* When the viewport is paused/draggable, the scroll element
       needs to be positioned in normal flow for scrollTop to work */
.notice-viewport.nb-draggable .notice-scroll {
    position: relative;
    animation: none;
    width: 100%;
    transform: none !important;
}

@keyframes noticeUp {
    0% {
        transform: translateY(100%);
    }

    100% {
        transform: translateY(-100%);
    }
}

.notice-scroll.paused {
    animation-play-state: paused;
}

