}

.tab-nav-bar {
    display: grid;
    grid-template-columns: repeat(3,1fr);
    background: #F8FAFC; /* Soft grey track background */
    padding: 8px; /* Inner padding for the track */
    border-bottom: 1px solid var(--col-border);
    position: relative;
    overflow: hidden;
}

    /* The Sliding Fluid Pill Background */
    .tab-nav-bar::after {
        content: '';
        position: absolute;
        top: 8px;
        bottom: 8px;
        left: 8px;
        width: calc(33.333% - 5.33px); /* Exact width minus padding */
        background: var(--col-primary);
        border-radius: var(--r-md);
        box-shadow: 0 4px 12px rgba(139, 26, 26, 0.25);
        transition: left .4s cubic-bezier(0.34, 1.56, 0.64, 1), background .4s var(--ease);
        z-index: 1;
    }

    .tab-nav-bar[data-active="lastdates"]::after {
        left: 8px;
        background: var(--col-primary);
    }

    .tab-nav-bar[data-active="schemes"]::after {
        left: calc(33.333% + 2.66px); /* Centers in the second slot */
        /*background: #DC2626*/;
        box-shadow: 0 4px 12px rgba(220, 38, 38, 0.25);
    }

    .tab-nav-bar[data-active="process"]::after {
        left: calc(66.666% - 2.66px); /* Centers in the third slot */
        /*background: #16A34A;*/
        box-shadow: 0 4px 12px rgba(22, 163, 74, 0.25);
    }

