    transition: none;
}

.qab-actions {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    position: relative;
    z-index: 1;
}

.qab-btn {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 9px 18px;
    border-radius: var(--r-pill);
    font-family: var(--ff-head);
    font-size: .82rem;
    font-weight: 700;
    text-decoration: none;
    transition: transform .22s var(--ease), box-shadow .22s var(--ease), background .22s var(--ease), color .22s var(--ease), border-color .22s var(--ease);
    white-space: nowrap;
    position: relative;
    overflow: hidden;
}

    .qab-btn:hover {
        transform: translateY(-2px);
        box-shadow: 0 6px 20px rgba(0,0,0,.28);
    }

    .qab-btn:active {
        transform: translateY(0) scale(.97);
    }

.qab-btn-primary {
    background: #fff;
    /* FIXED: Make button text match the active theme */
    color: var(--col-primary);
    border: 2px solid #fff;
}

    .qab-btn-primary:hover {
        background: #f0f4ff;
        color: var(--col-primary-d);
        border-color: #f0f4ff;
    }

.qab-btn-outline {
    background: rgba(255,255,255,.12);
    color: #fff;
    border: 2px solid rgba(255,255,255,.45);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
}

    .qab-btn-outline:hover {
        background: rgba(255,255,255,.25);
        color: #fff;
        border-color: rgba(255,255,255,.75);
    }

@media(max-width:640px) {
    .quick-apply-banner {
        grid-template-columns: 1fr;
        padding: 18px 18px;
    }

    .qab-actions {
        justify-content: flex-start;
        flex-wrap: wrap;
        gap: 8px;
    }

    .qab-btn {
        font-size: .78rem;
        padding: 8px 14px;
        gap: 6px;
    }
}

@media(max-width:400px) {
    .qab-actions {
        flex-direction: column;
        align-items: stretch;
    }

    .qab-btn {
        justify-content: center;
        width: 100%;
    }
}

/* ══════════════════════════════════════════════
   SUPPORT & HELPLINE
══════════════════════════════════════════════ */
.helpline-section {
    margin: 8px 0 28px
}

.helpline-section-header {
    text-align: center;
    margin-bottom: 18px
}

    .helpline-section-header h2 {
        font-family: var(--ff-head);
        font-size: 1.15rem;
        font-weight: 700;
        color: var(--col-head);
        display: inline-flex;
        align-items: center;
        gap: 10px;
        transition: color .4s var(--ease)
    }

        .helpline-section-header h2::before, .helpline-section-header h2::after {
            content: '';
            display: block;
            width: 36px;
            height: 2px;
            background: var(--col-primary);
            border-radius: 2px
        }

/* ══════════════════════════════════════════════
   SUPPORT & HELPLINE (Modern Interactive Cards)
══════════════════════════════════════════════ */
.helpline-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
}

.helpline-card-wide {
    grid-column: span 1;
}

@media(min-width: 901px) {
    .helpline-card-wide {
        grid-column: span 3; /* Allows the last wide card to span across all 3 columns cleanly */
    }
}

@media(max-width: 900px) {
    .helpline-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .helpline-card-wide {
        grid-column: span 2;
    }
}

@media(max-width: 560px) {
    .helpline-grid {
        grid-template-columns: 1fr;
    }

    .helpline-card-wide {
        grid-column: span 1;
    }
}

.helpline-card {
    background: #ffffff;
    border-radius: 16px;
    border: 1px solid rgba(226, 232, 240, 0.8);
    padding: 18px 20px;
    display: flex;
    gap: 16px;
    align-items: center;
    box-shadow: 0 4px 15px -3px rgba(0,0,0,0.03), 0 2px 6px -2px rgba(0,0,0,0.02);
    transition: transform 0.35s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.35s ease, border-color 0.35s ease;
    position: relative;
    overflow: hidden;
}

    /* Hover Lift */
    .helpline-card:hover {
        transform: translateY(-4px);
        box-shadow: 0 12px 28px -6px rgba(15, 23, 42, 0.08);
        border-color: rgba(26, 58, 139, 0.2);
    }

/* Department Icon Badge (Squircle with soft shadow) */
.hc-icon {
    width: 44px;
    height: 44px;
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.1rem;
    flex-shrink: 0;
    box-shadow: 0 4px 10px rgba(0,0,0,0.05);
    transition: transform 0.35s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.helpline-card:hover .hc-icon {
    transform: scale(1.1) rotate(-4deg);
}

/* Department Name */
.hc-dept {
    font-family: var(--ff-head);
    font-size: 0.92rem;
    font-weight: 800;
    color: var(--col-head);
    margin-bottom: 6px;
    line-height: 1.3;
}

/* Phone Number Styling */
.hc-number {
    font-size: 0.9rem;
    font-weight: 700;
    color: var(--col-primary);
    font-family: var(--ff-head);
    display: flex;
    align-items: center;
    gap: 6px;
    flex-wrap: wrap;
    margin-bottom: 4px;
}

    .hc-number i {
        font-size: 0.8rem;
        opacity: 0.8;
    }

/* Email / Note Links */
.hc-email {
    font-size: 0.8rem;
    color: var(--col-muted);
    word-break: break-word;
    display: flex;
    align-items: center;
    gap: 6px;
}

    .hc-email a {
        color: var(--col-muted);
        text-decoration: none;
        font-weight: 500;
        transition: color 0.2s ease;
    }

        .hc-email a:hover {
            color: var(--col-primary);
            text-decoration: underline;
        }

/* ── Dark Theme Overrides ── */
body[data-theme="dark"] .helpline-card {
    background: #1E293B;
    border-color: #334155;
    box-shadow: 0 4px 15px -3px rgba(0,0,0,0.3);
}

    body[data-theme="dark"] .helpline-card:hover {
        border-color: rgba(96, 165, 250, 0.3);
        box-shadow: 0 12px 28px -6px rgba(0,0,0,0.5);
    }

body[data-theme="dark"] .hc-dept {
    color: #F1F5F9;
}

body[data-theme="dark"] .hc-number {
    color: #60A5FA;
}

body[data-theme="dark"] .hc-email a:hover {
    color: #60A5FA;
}

/* Policy bar */
.policy-bar {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 6px 4px;
    padding: 14px 0;
    border-top: 1px solid var(--col-border);
    border-bottom: 1px solid var(--col-border);
    margin: 14px 0 0;
    transition: border-color .4s var(--ease)
}

.policy-link {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    font-size: .78rem;
    font-weight: 500;
    color: var(--col-muted);
    text-decoration: none;
    padding: 5px 13px;
    border-radius: var(--r-pill);
    border: 1px solid var(--col-border);
    transition: var(--tr);
    background: var(--col-card)
}

    .policy-link:hover {
        background: var(--col-primary);
        color: #fff;
        border-color: var(--col-primary)
    }

/* ══════════════════════════════════════════════
   FOOTER — larger logos + marquee scroll (Point 12)
══════════════════════════════════════════════ */
.portal-footer {
    background: #0F172A;
    color: #94A3B8;
    border-top: 4px solid var(--col-accent);
    padding: 0 16px 16px
}

.footer-inner {
    max-width: 1400px;
    margin: 0 auto
}

.footer-grid {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 24px;
    margin-bottom: 20px;
    padding-bottom: 20px;
    border-bottom: 1px solid rgba(255,255,255,.07)
}

@media(max-width:768px) {
    .footer-grid {
        grid-template-columns: 1fr;
        gap: 14px
    }
}

.footer-col-title {
    font-family: var(--ff-head);
    font-size: .75rem;
    font-weight: 700;
    letter-spacing: 1.2px;
    text-transform: uppercase;
    color: #fff;
    margin-bottom: 8px
}

.footer-text {
    font-size: .8rem;
    line-height: 1.65;
    color: #64748B
}

    .footer-text strong {
        color: #94A3B8
    }

.footer-stats {
    display: flex;
    gap: 14px;
    flex-wrap: wrap
}

.footer-stat-box {
    background: rgba(255,255,255,.04);
    border: 1px solid rgba(255,255,255,.07);
    border-radius: var(--r-sm);
    padding: 9px 14px;
    text-align: center;
    min-width: 100px
}

.footer-stat-label {
    font-size: .67rem;
    color: #64748B;
    text-transform: uppercase;
    letter-spacing: .8px
}

.footer-stat-value {
    font-family: var(--ff-head);
    font-size: .95rem;
    font-weight: 700;
    color: #F1F5F9;
    margin-top: 2px
}

/* Footer logos — LARGER + marquee scroll (Point 12) */
.footer-logos-track {
    overflow: hidden;
    padding: 14px 0;
    border-top: 1px solid rgba(255,255,255,.07);
    position: relative
}

    .footer-logos-track::before, .footer-logos-track::after {
        content: '';
        position: absolute;
        top: 0;
        bottom: 0;
        width: 60px;
        z-index: 2;
        pointer-events: none
    }

    .footer-logos-track::before {
        left: 0;
        background: linear-gradient(to right,#0F172A,transparent)
    }

    .footer-logos-track::after {
        right: 0;
        background: linear-gradient(to left,#0F172A,transparent)
    }

.footer-logos-scroll {
    display: flex;
    gap: 32px;
    align-items: center;
    animation: logoScroll 20s linear infinite;
    width: max-content
}

    .footer-logos-scroll:hover {
        animation-play-state: paused
    }

@keyframes logoScroll {
    0% {
        transform: translateX(0)
    }

    100% {
        transform: translateX(-50%)
    }
}

.footer-logos-scroll img {
    height: 48px;
    width: auto;
    object-fit: contain;
    opacity: .65;
    transition: opacity .25s,filter .25s;
    filter: grayscale(.5) brightness(1.3)
}

    .footer-logos-scroll img:hover {
        opacity: 1;
        filter: none
    }

.footer-copy {
    text-align: center;
    font-size: 15px;
    color: #ffffff;
    margin-top: 14px;
    padding-top: 12px;
    border-top: 1px solid rgba(255,255,255,.05)
}

/* ══════════════════════════════════════════════
   SCROLL TO TOP (Circular SVG Progress)
══════════════════════════════════════════════ */
.scroll-to-top-wrap {
    position: fixed;
    bottom: 24px;
    right: 22px;
    width: 52px;
    height: 52px;
    z-index: 9999;
    opacity: 0;
    visibility: hidden;
    transform: translateY(15px);
    transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
    cursor: pointer;
}

    .scroll-to-top-wrap.show {
        opacity: 1;
        visibility: visible;
        transform: translateY(0);
    }

.progress-ring {
    position: absolute;
    top: 0;
    left: 0;
    transform: rotate(-90deg);
}

.progress-ring-bg {
    stroke: rgba(26, 58, 139, 0.15);
}

.progress-ring-circle {
    stroke: #10B981;
    transition: stroke-dashoffset 0.1s linear;
}

/* Updated Button Styles - Overrides any hidden states */
#scrollTopBtn {
    position: absolute !important;
    top: 50% !important;
    left: 50% !important;
    transform: translate(-50%, -50%) !important;
    width: 36px !important;
    height: 36px !important;
    background: #1A3A8B !important;
    border: none !important;
    border-radius: 50% !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    opacity: 1 !important; /* Forces it to be visible */
    visibility: visible !important; /* Forces it to be visible */
    pointer-events: none !important; /* Lets clicks pass to the wrapper */
    box-shadow: 0 4px 10px rgba(0,0,0,0.15);
    transition: all 0.3s ease;
    z-index: 2;
}

    /* Explicitly size and color the arrow icon */
    #scrollTopBtn i {
        color: #ffffff !important;
        font-size: 1.1rem !important;
        display: block !important;
    }

/* Hover effect applied to the wrapper */
.scroll-to-top-wrap:hover #scrollTopBtn {
    background: #122970 !important;
    transform: translate(-50%, -50%) scale(1.08) !important;
}

@media(max-width:480px) {
    #scrollTopBtn {
        bottom: 16px;
        right: 14px;
        width: 36px;
        height: 36px;
        font-size: .85rem
    }
}

/* ── REVEAL ANIMATIONS — enhanced with scale+slide ── */
.reveal {
    opacity: 0;
    transform: translateY(20px) scale(.985);
    transition: opacity .55s var(--ease), transform .55s var(--ease);
}

    .reveal.visible {
        opacity: 1;
        transform: translateY(0) scale(1);
    }

.d1 {
    transition-delay: .07s;
}

.d2 {
    transition-delay: .16s;
}

.d3 {
    transition-delay: .25s;
}

.d4 {
    transition-delay: .34s;
}

/* ══════════════════════════════════════════════
   ELIGIBILITY POPUP MODAL (Point 9)
══════════════════════════════════════════════ */
.elig-modal-overlay {
    display: none;
    position: fixed;
    inset: 0;
    background: rgba(0,0,0,.55);
    z-index: 2000;
    align-items: center;
    justify-content: center;
    padding: 16px
}

    .elig-modal-overlay.open {
        display: flex
    }

.elig-modal {
    background: var(--col-card);
    border-radius: var(--r-xl);
    box-shadow: var(--sh-lg);
    max-width: 560px;
    width: 100%;
    max-height: 85vh;
    overflow: hidden;
    display: flex;
    flex-direction: column;
    animation: popIn .28s var(--ease)
}

@keyframes popIn {
    from {
        opacity: 0;
        transform: scale(.92) translateY(12px)
    }

    to {
        opacity: 1;
        transform: none
    }
}

.elig-modal-head {
    padding: 16px 20px;
    border-bottom: 1px solid var(--col-border);
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-shrink: 0
}

.elig-modal-title {
    font-family: var(--ff-head);
    font-size: 1rem;
    font-weight: 700;
    color: var(--col-head);
    flex: 1;
    margin-right: 12px
}

.elig-modal-close {
    background: var(--col-bg);
    border: 1px solid var(--col-border);
    border-radius: 50%;
    width: 30px;
    height: 30px;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    font-size: .8rem;
    transition: var(--tr)
}

    .elig-modal-close:hover {
        background: var(--col-primary);
        color: #fff;
        border-color: var(--col-primary)
    }

.elig-modal-body {
    padding: 16px 20px;
    overflow-y: auto;
    flex: 1
}

.elig-row {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    padding: 9px 12px;
    border-radius: var(--r-sm);
    margin-bottom: 7px;
    background: var(--col-bg);
    border: 1px solid var(--col-border);
    transition: background .4s var(--ease)
}

.elig-badge {
    background: var(--col-primary);
    color: #fff;
    font-size: .68rem;
    font-weight: 250;
    padding: 2px 8px;
    border-radius: var(--r-pill);
    white-space: nowrap;
    flex-shrink: 0
}

.elig-desc {
    font-size: .83rem;
    color: var(--col-text);
    line-height: 1.5
}

.elig-loading {
    text-align: center;
    padding: 24px;
    color: var(--col-muted);
    font-size: .85rem
}

