/* ══════════════════════════════════════════════
   PRE / POST TOGGLE WRAPPER (Click Only)
══════════════════════════════════════════════ */
.prepost-toggle-wrap {
    display: flex;
    justify-content: center;
    margin: 12px 0 24px;
    padding: 0 16px;
}

/* The track */
.prepost-pill {
    display: inline-grid;
    grid-template-columns: 1fr 1fr;
    align-items: stretch;
    background: var(--pp-track, #E8EDF5);
    border-radius: 999px;
    padding: 4px;
    gap: 0;
    box-shadow: inset 0 2px 6px rgba(0,0,0,.10), inset 0 0 0 1px rgba(0,0,0,.06);
    position: relative;
    width: 100%;
    max-width: 480px;
    -webkit-user-select: none;
    user-select: none;
    isolation: isolate; /* FIX: Guarantees background stays behind text */
}

    /* The animated sliding thumb */
    .prepost-pill::before {
        content: '';
        position: absolute;
        top: 4px;
        left: 4px;
        width: calc(50% - 4px);
        height: calc(100% - 8px);
        background: var(--col-primary);
        border-radius: 999px;
        box-shadow: 0 4px 16px rgba(0,0,0,.24), 0 1px 4px rgba(0,0,0,.15);
        transition: transform .32s cubic-bezier(.4,0,.2,1), background .28s ease;
        transform: translateX(0);
        will-change: transform;
        z-index: 1; /* FIX: Places thumb correctly */
    }

    /* Thumb moves right for second btn */
    .prepost-pill[data-active="1"]::before {
        transform: translateX(100%);
        background: var(--col-primary);
    }

/* The buttons */
.pp-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    padding: 10px 14px;
    background: transparent;
    border: none;
    font-family: var(--ff-head, 'Outfit', sans-serif);
    font-size: .84rem;
    font-weight: 600;
    color: var(--col-muted);
    cursor: pointer;
    transition: color .24s ease;
    white-space: normal;
    word-break: keep-all;
    text-align: center;
    line-height: 1.3;
    min-height: 44px;
    position: relative; /* FIX: Required for z-index to work */
    z-index: 2; /* FIX: Forces text to float ABOVE the blue thumb */
    pointer-events: auto !important; /* FIX: Re-enables mouse clicks! */
}

    .pp-btn i {
        font-size: .88rem;
        transition: transform .32s cubic-bezier(.34,1.56,.64,1);
    }

    .pp-btn.pp-active {
        color: #fff;
    }

        .pp-btn.pp-active i {
            transform: scale(1.15) rotate(-4deg);
        }

    /* Remove default browser focus outlines if clicked */
    /* Provide a clear focus ring for keyboard users, but hide it for mouse clicks */
    .pp-btn:focus-visible {
        outline: 3px solid var(--col-primary);
        outline-offset: 2px;
        border-radius: 999px;
    }

    .pp-btn:focus:not(:focus-visible) {
        outline: none;
    }

/* ── PP PANEL TRANSITIONS ──
   We use max-height + opacity so display:none doesn't kill animation */
.pp-panel {
    display: block; /* always in DOM */
    overflow: hidden;
    max-height: 0;
    opacity: 0;
    transform: translateX(0);
    transition: max-height .38s cubic-bezier(.4,0,.2,1), opacity .28s ease, transform .28s ease;
    pointer-events: none;
}

    .pp-panel.pp-show {
        max-height: 2000px; /* large enough for any content */
        opacity: 1;
        pointer-events: auto;
        transition: max-height .38s cubic-bezier(.4,0,.2,1), opacity .3s ease .05s, transform .3s ease .05s;
    }

    /* Direction helpers added by JS */
    .pp-panel.pp-from-right {
        transform: translateX(18px);
    }

    .pp-panel.pp-from-left {
        transform: translateX(-18px);
    }

    .pp-panel.pp-show.pp-from-right,
    .pp-panel.pp-show.pp-from-left {
        transform: translateX(0);
    }

/* ── PILL RESPONSIVE ── */
/* Tablet / large mobile */
@media(max-width:600px) {
    .prepost-toggle-wrap {
        margin-bottom: 14px;
        padding: 0 2px;
    }

    .prepost-pill {
        max-width: 100%;
    }

    .pp-btn {
        font-size: .78rem;
        padding: 9px 10px;
        gap: 5px;
    }

        .pp-btn i {
            font-size: .8rem;
            flex-shrink: 0;
        }
}

/* Small mobile */
@media(max-width:420px) {
    .pp-btn {
        font-size: .72rem;
        padding: 8px 8px;
        gap: 4px;
    }

    .pp-sub {
        font-size: .68em;
    }
}

/* Very small — hide sub-label */
@media(max-width:360px) {
    .pp-sub {
        display: none;
    }

    .pp-btn {
        font-size: .72rem;
        padding: 8px 6px;
    }
}

