body[data-theme="dark"] .prepost-pill {
    background: #1E293B;
    box-shadow: inset 0 2px 6px rgba(0,0,0,.3), inset 0 0 0 1px rgba(255,255,255,.05);
}

body[data-theme="dark"] .pp-btn {
