@keyframes ppFadeIn {
    from {
        opacity: 0;
        transform: translateY(4px);
    }

    to {
        opacity: 1;
        transform: none;
    }
}

@keyframes ppSlideIn {
    from {
        opacity: 0;
        transform: translateX(12px) scale(.98);
    }

    to {
        opacity: 1;
        transform: translateX(0) scale(1);
    }
}

@keyframes ppSlideInLeft {
    from {
        opacity: 0;
        transform: translateX(-12px) scale(.98);
    }

    to {
        opacity: 1;
        transform: translateX(0) scale(1);
    }
}

