    font-weight: 700;
    color: var(--col-primary);
    margin-bottom: 24px;
    display: flex;
    align-items: center;
    gap: 10px;
}

.process-timeline {
    display: flex;
    flex-direction: column;
    gap: 16px;
    position: relative;
    padding-left: 24px;
    border-left: 2px dashed var(--col-border);
    margin-left: 12px;
}

.timeline-step {
    display: flex;
    align-items: center;
    position: relative;
}

.step-number {
    width: 32px;
    height: 32px;
    background: #EBF0FB; /* Light blue */
    color: #1A3A8B; /* Primary blue */
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 800;
    font-size: 0.9rem;
    position: absolute;
    left: -41px; /* Aligns precisely over the dashed border */
    top: 50%;
    transform: translateY(-50%);
    box-shadow: 0 0 0 6px var(--col-card); /* Creates the "cutout" effect over the border */
}

body[data-theme="dark"] .step-number {
    background: #1E3A5F;
    color: #60A5FA;
    box-shadow: 0 0 0 6px #1E293B;
}

.step-content {
    background: var(--col-bg);
    padding: 12px 16px;
    border-radius: var(--r-sm);
    width: 100%;
    border: 1px solid transparent;
    font-size: 0.88rem;
    color: var(--col-text);
    transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1), border-color 0.3s ease, box-shadow 0.3s ease;
}

    .step-content:hover {
        transform: translateX(6px);
        border-color: rgba(26, 58, 139, 0.3);
        background: var(--col-card);
        box-shadow: var(--sh-xs);
    }

/* ══════════════════════════════════════════════
   EXTERNAL LINK (TARGET BLANK) HOVER ARROWS
══════════════════════════════════════════════ */
/* Ensures the absolute position of the arrow stays inside the button/link */
a[target="_blank"] {
    position: relative;
}

    /* Base configuration for the arrow icon */
    a[target="_blank"]::after {
        content: '\f08e'; /* FontAwesome 'up-right-from-square' icon */
        font-family: 'Font Awesome 7 Pro', 'Font Awesome 6 Pro', 'FontAwesome'; /* Updated for Pro Versions */
        font-weight: 900; /* Pro Solid. Use 400 for Regular, or 300 for Light */
        font-size: 0.85em;
        opacity: 0;
        pointer-events: none; /* Prevents the icon from blocking clicks */
        transition: opacity 0.3s ease, transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
    }

/* 1. Applicant Corner & Department Corner Links */
.info-link-item a[target="_blank"] {
    padding-right: 32px; /* Make space for the arrow so text doesn't overlap */
}

    .info-link-item a[target="_blank"]::after {
        position: absolute;
        right: 14px;
        top: 50%;
        transform: translate(-8px, -20%); /* Start slightly down and left */
        color: var(--col-primary);
    }

    .info-link-item a[target="_blank"]:hover::after {
        opacity: 1;
        transform: translate(0, -50%); /* Slide smoothly to center right */
    }

/* 2. Quick Apply Banner Buttons */
.qab-btn[target="_blank"] {
    padding-right: 34px;
}

    .qab-btn[target="_blank"]::after {
        position: absolute;
        right: 16px;
        top: 50%;
        transform: translate(-6px, -20%);
    }

    .qab-btn[target="_blank"]:hover::after {
        opacity: 1;
        transform: translate(0, -50%);
    }

/* 3. Notice Board & Ticker Links (Inline Text layout) */
.notice-item a[target="_blank"],
.ticker-inner a[target="_blank"] {
    display: inline-block;
    padding-right: 20px;
}

    .notice-item a[target="_blank"]::after,
    .ticker-inner a[target="_blank"]::after {
        position: absolute;
        right: 0;
        top: 50%;
        transform: translate(-6px, -20%);
        color: var(--col-primary);
    }

    .notice-item a[target="_blank"]:hover::after,
    .ticker-inner a[target="_blank"]:hover::after {
        opacity: 1;
        transform: translate(0, -50%);
    }

/* --- Dark Theme Overrides --- */
body[data-theme="dark"] .info-link-item a[target="_blank"]::after,
body[data-theme="dark"] .notice-item a[target="_blank"]::after,
body[data-theme="dark"] .ticker-inner a[target="_blank"]::after {
    color: var(--col-accent); /* Brighter blue for dark mode */
}

/* ══════════════════════════════════════════════
   1. ADVANCED GLASSMORPHISM & NOISE TEXTURE
══════════════════════════════════════════════ */
:root {
    /* Generates a mathematical SVG noise texture pattern */
    --noise-bg: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E");
}

/*.top-bar, .stats-bar {
    position: relative;
}*/

/* Layer the noise texture over the glassmorphism bars */
.top-bar::after, .stats-bar::after {
    content: '';
    position: absolute;
    inset: 0;
    background: var(--noise-bg);
    opacity: 0.035; /* Extremely subtle film-grain texture */
    mix-blend-mode: overlay;
    pointer-events: none;
    z-index: 0;
}

.top-bar-inner, .stat-item {
    position: relative;
    /*z-index: 1;*/ /* Keep text above the noise */
}

/* ══════════════════════════════════════════════
   2. DYNAMIC SPOTLIGHT EFFECT (Cards & Blocks)
══════════════════════════════════════════════ */
.spotlight-card {
    position: relative;
    overflow: hidden;
}

    /* Elevate card contents so the spotlight slides underneath them */
    .spotlight-card > * {
        position: relative;
        z-index: 2;
    }

    /* The invisible spotlight light source */
    .spotlight-card::before {
        content: '';
        position: absolute;
        inset: 0;
        /* Uses CSS variables updated by Javascript */
        background: radial-gradient( 600px circle at var(--mouse-x, 0) var(--mouse-y, 0), rgba(255, 255, 255, 0.35), transparent 40% );
        z-index: 1;
        pointer-events: none;
        opacity: 0;
        transition: opacity 0.5s ease;
    }

    .spotlight-card:hover::before {
        opacity: 1;
    }

body[data-theme="dark"] .spotlight-card::before {
    background: radial-gradient( 600px circle at var(--mouse-x, 0) var(--mouse-y, 0), rgba(255, 255, 255, 0.08), transparent 40% );
}

/* ══════════════════════════════════════════════
   3. STAGGERED CASCADE TAB ANIMATIONS
══════════════════════════════════════════════ */
.tab-pane.active .ld-card,
.tab-pane.active .ssp-acc-item,
.tab-pane.active .timeline-step {
    animation: cascadeFadeUp 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards;
    opacity: 0;
    transform: translateY(20px);
}

@keyframes cascadeFadeUp {
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

/* Stagger the delay mathematically for a fluid wave effect */
.tab-pane.active .ld-card:nth-child(1), .tab-pane.active .ssp-acc-item:nth-child(1), .tab-pane.active .timeline-step:nth-child(1) {
    animation-delay: 0.05s;
}

.tab-pane.active .ld-card:nth-child(2), .tab-pane.active .ssp-acc-item:nth-child(2), .tab-pane.active .timeline-step:nth-child(2) {
    animation-delay: 0.10s;
}

.tab-pane.active .ld-card:nth-child(3), .tab-pane.active .ssp-acc-item:nth-child(3), .tab-pane.active .timeline-step:nth-child(3) {
    animation-delay: 0.15s;
}

.tab-pane.active .ld-card:nth-child(4), .tab-pane.active .ssp-acc-item:nth-child(4), .tab-pane.active .timeline-step:nth-child(4) {
    animation-delay: 0.20s;
}

.tab-pane.active .ld-card:nth-child(5), .tab-pane.active .ssp-acc-item:nth-child(5), .tab-pane.active .timeline-step:nth-child(5) {
    animation-delay: 0.25s;
}

.tab-pane.active .ld-card:nth-child(n+6), .tab-pane.active .ssp-acc-item:nth-child(n+6), .tab-pane.active .timeline-step:nth-child(n+6) {
    animation-delay: 0.30s;
}

/* ══════════════════════════════════════════════
   4. SLEEK SKELETON LOADER (For Eligibility Modal)
══════════════════════════════════════════════ */
.skeleton-loader {
    display: flex;
    flex-direction: column;
    gap: 12px;
    padding: 10px 4px;
}

.skeleton-row {
    height: 18px;
    background: linear-gradient(90deg, #F1F5F9 25%, #E2E8F0 50%, #F1F5F9 75%);
    background-size: 200% 100%;
    animation: skeletonPulse 1.5s infinite linear;
    border-radius: 6px;
}

    .skeleton-row.pill {
        width: 35%;
        height: 26px;
        border-radius: 999px;
        margin-bottom: 6px;
    }

    .skeleton-row.long {
        width: 95%;
    }

    .skeleton-row.med {
        width: 75%;
    }

@keyframes skeletonPulse {
    0% {
        background-position: 200% 0;
    }

    100% {
        background-position: -200% 0;
    }
}

body[data-theme="dark"] .skeleton-row {
    background: linear-gradient(90deg, #1E293B 25%, #334155 50%, #1E293B 75%);
}


