}

/* ══════════════════════════════════════════════
   WIDESCREEN FLUID LAYOUT OVERRIDE
══════════════════════════════════════════════ */
/* Expands the main containers to utilize more space on large monitors */
.top-bar-inner,
.header-brand-inner,
.carousel-section,
.main-wrapper,
.stats-bar,
