/* ══════════════════════════════════════════════
   MOBILE STATS BAR TEXT OVERFLOW FIX
══════════════════════════════════════════════ */
@media (max-width: 768px) {
    .stat-item {
        /* Reduces side padding to give the long number more room to breathe */
        padding: 20px 8px !important;
    }

