/* --- TABLET Adjustments --- */
@media (max-width: 1100px) {
    .header-left-cm img {
        height: 80px;
    }

    .header-right-logo img {
        height: 75px;
    }

    .header-center-gok .gov-name {
        font-size: 1rem;
    }

    .header-center-gok .ssp-name {
        font-size: 0.85rem;
    }
}

/* --- MOBILE Adjustments (Perfect Stacking) --- */
@media (max-width: 768px) {
    .new-header-layout {
        flex-wrap: wrap; /* Critical rule for stacking */
        padding: 8px 0;
        gap: 12px;
    }

    /* Force Center block to top, full width */
    .header-center-gok {
        order: 1;
        flex: 0 0 100%;
        flex-direction: row;
        justify-content: center;
    }

    /* CM Left & PKIT Right take exactly 48% each on the 2nd row */
    .header-left-cm {
        order: 2;
        flex: 0 0 48%;
        justify-content: flex-start;
    }

    .header-right-logo {
        order: 3;
        flex: 0 0 48%;
        justify-content: flex-end;
    }

    /* Scale down images safely without clipping */
    .header-gok-emblem img {
        height: 50px;
    }

    /* Force images to scale proportionally inside their 48% columns */
    .header-left-cm img {
        height: auto;
        max-height: 60px;
        width: 100%;
        object-fit: contain;
        object-position: left center; /* Hugs the left edge */
    }

    .header-right-logo img {
        height: auto;
        max-height: 60px;
        width: 100%;
        object-fit: contain;
        object-position: right center; /* Hugs the right edge */
    }

    .header-center-gok .gov-name {
        font-size: 0.95rem;
