.settings-dropdown {
    position: relative;
}

.settings-menu {
    position: absolute;
    top: calc(100% + 12px);
    right: 0;
    background: linear-gradient(135deg, var(--col-primary) 0%, var(--col-primary-d) 100%);
    border: 1px solid rgba(255,255,255,0.15);
    border-radius: var(--r-md);
    box-shadow: 0 10px 30px rgba(0,0,0,0.35);
    padding: 18px;
    display: flex;
    flex-direction: column;
    gap: 18px;
    min-width: 220px;
    max-width: calc(100vw - 20px); /* Prevents overflow on tiny phones */
    opacity: 0;
    visibility: hidden;
    transform: translateY(-10px);
    transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
    z-index: 1060;
}

/* Show State triggered by JS */
.settings-dropdown.active .settings-menu {
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
}

.settings-menu-item {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.settings-label {
    font-size: 0.75rem;
    color: rgba(255,255,255,0.7);
