:root{
--primary-color: #0091a0;
--text-color: rgba(0,0,0,0.65);
--light-color: #ffffff;
--elevation-1: 0px 1px 4px rgba(0, 0, 0, 0.08), 0px 1px 2px rgba(0, 0, 0, 0.12);
--elevation-2: 0px 2px 8px rgba(0, 0, 0, 0.08), 0px 2px 4px rgba(0, 0, 0, 0.12);
--elevation-3: 0px 3px 12px rgba(0, 0, 0, 0.08), 0px 3px 6px rgba(0, 0, 0, 0.12);
}
.quote-container{    height: 150px;
overflow: auto;}
.as-container{
display:flex;
height:100%;
justify-content:center;
align-items:center;
}
.as-choice-card{
position:relative;
display:flex;
flex-direction: column;
align-items:center;
padding:25px 0px 8px 0px;
margin-bottom: 12px;
text-align: center;
box-shadow: var(--elevation-1);
background-color:#ffffff;
cursor: pointer;
}
.as-choice-card *{
position:relative;
z-index:2;
}
.as-choice-card img{
width: 40%;
}
.rp{padding: 30px !important;}
.as-choice-card:after{
content: '';
position:absolute;
top:0;
left:0;
width:4px;
height:100%;
background-color:var(--primary-color);
transition: ease-in-out .3s;
z-index:0;
}
.as-card-icon{
position:absolute;
display:flex;
justify-content:center;
align-items:center;
width:72px;
height:72px;
top: -36px;
font-size: 25px;
color:var(--light-color);
background-color:var(--primary-color);
border-radius:50%;
box-shadow: var(--elevation-2);
transition: ease-in-out .3s;
}
.as-card-title,
.as-card-info{
transition:ease-in-out .3s;
}
.as-card-info{
width: 403px;
padding-bottom:10px;
margin:0;
}
.as-card-cta{
padding: 12px 36px;
border-radius:30px;
border:none;
background: linear-gradient(to right, #006cc7, #019e8b);
color: var(--light-color);
box-shadow: var(--elevation-3);
transition: ease-in-out .3s;
}
.as-choice-card:hover{
--text-color: #FFFFFF;
--primary-color: #ffffff;
--light-color: #0D6FFA;
color: var(--text-color);
}
.as-choice-card:hover h3{
color:black;
}
.as-choice-card a:hover,.as-choice-card a{color: white !important;}
.as-choice-card:hover:after{
--primary-color: #dddded;
width:100%;
}
