.text_effect {
position: relative;
display:inline-block;
z-index: 9;
padding-top: 25px;
padding-left: 5px;
}
.text_effect h4 span{
font-size:18px;
color:#fff;
font-weight:600;
display:block;
float:left;
text-transform:uppercase;
position:relative;
letter-spacing:0px;
animation: animate 2.25s linear infinite;
}
.text_effect h4 span:nth-child(1){
animation-delay: 0s;
}
.text_effect h4 span:nth-child(2){
animation-delay: .25s;
}
.text_effect h4 span:nth-child(2){
animation-delay: .5s;
}
.text_effect h4 span:nth-child(3){
animation-delay: .75s;
}
.text_effect h4 span:nth-child(4){
animation-delay: 1s;
}
.text_effect h4 span:nth-child(5){
animation-delay: 1.25s;
}
.text_effect h4 span:nth-child(6){
animation-delay: 1.5s;
}
.text_effect h4 span:nth-child(7){
animation-delay: 1.75s;
}
@keyframes animate {
0%, 100%{
color: #fff;
filter: blur(2px);
text-shadow: 0 0 10px #ffffff, 0 0 20px #ffffff, 0 0 40px #ffffff, 0 0 80px #ffffff, 0 0 120px #ffffff, 0 0 200px #ffffff, 0 0 300px #ffffff, 0 0 400px #ffffff;
}
5%, 95%{
color: #fff;
filter: blur(0px);
text-shadow: none;
}
}
