* 10. TESTIMONIAL STYLE
* ----------------------------------------------------------------------------------------
*/
.box-testimony {
margin: 30px 15px;
}
.box-testimony blockquote {
border-left: none;
padding: 40px;
background: transparent;
border: 1px solid #666;
position: relative;
font-size: 16px;
-webkit-border-radius: 4px;
-moz-border-radius: 4px;
-ms-border-radius: 4px;
border-radius: 4px;
-webkit-transition: all 0.4s ease 0s;
-moz-transition: all 0.4s ease 0s;
-o-transition: all 0.4s ease 0s;
transition: all 0.4s ease 0s;
}
.box-testimony blockquote:after {
content: "";
position: absolute;
top: 100%;
left: 47%;
border-top: 15px solid #666;
border-left: 15px solid transparent;
border-right: 15px solid transparent;
-webkit-transition: all 0.4s ease 0s;
-moz-transition: all 0.4s ease 0s;
-o-transition: all 0.4s ease 0s;
transition: all 0.4s ease 0s;
}
.box-testimony blockquote .quote {
position: absolute;
top: 0;
left: 44%;
text-align: center;
font-size: 30px;
line-height: 0;
display: table;
color: #333;
width: 56px;
height: 56px;
margin-top: -30px;
background: #fff;
border: 1px solid #e9e9e9;
-webkit-border-radius: 50%;
-moz-border-radius: 50%;
-ms-border-radius: 50%;
border-radius: 50%;
-webkit-transition: all 0.4s ease 0s;
-moz-transition: all 0.4s ease 0s;
-o-transition: all 0.4s ease 0s;
transition: all 0.4s ease 0s;
}
.box-testimony blockquote .quote > span {
display: table-cell;
vertical-align: middle;
}
.box-testimony blockquote p {
color: #fff;
line-height: 28px;
}
.box-testimony .author {
color: #fff;
font-size: 18px;
text-transform: uppercase;
margin-bottom: 10px;
}
.box-testimony .author .subtext {
display: block;
font-size: 14px;
}
.box-testimony:hover.box-testimony blockquote {
background: #337ab7;
}
.box-testimony:hover.box-testimony blockquote {
color: #fff;
}
.box-testimony:hover.box-testimony blockquote .quote {
color: #fff;
border-color: #337ab7;
background: #337ab7;
}
.box-testimony.box-testimony:hover blockquote:after {
border-top: 15px solid #337ab7;
}
.client-testimonial.owl-theme .owl-controls .owl-page span {
width: 15px;
height: 15px;
line-height: 15px;
border-radius: 0;
position: relative;
background: transparent;
border: 1px solid #666;
opacity: 1;
}
.client-testimonial.owl-theme .owl-controls .owl-page.active span {
border-color: #337ab7;
}
.client-testimonial.owl-theme .owl-controls .owl-page span:before {
background: #fff none repeat scroll 0 0;
border-radius: 100%;
-webkit-border-radius: 100%;
-moz-border-radius: 100%;
-ms-border-radius: 100%;
content: "";
height: 7px;
left: 0;
margin: -3.5px auto 0;
position: absolute;
right: 0;
top: 50%;
width: 7px;
}
.client-testimonial.owl-theme .owl-controls .owl-page.active span:before {
background: #337ab7 none repeat scroll 0 0;
}
