description:
.nivoSlider {
position: relative;
width: 100%;
height: auto;
overflow: hidden;
}
.nivoSlider img {
position: absolute;
top: 0px;
left: 0px;
max-width: none;
}
.nivo-main-image {
display: block !important;
position: relative !important;
width: 100% !important;
}
/* If an image is wrapped in a link */
.nivoSlider a.nivo-imageLink {
position: absolute;
top: 0px;
left: 0px;
width: 100%;
height: 100%;
border: 0;
padding: 0;
margin: 0;
z-index: 6;
display: none;
background: white;
filter: alpha(opacity=0);
opacity: 0;
}
/* The slices and boxes in the Slider */
.nivo-slice {
display: block;
position: absolute;
z-index: 5;
height: 100%;
top: 0;
}
.nivo-box {
display: block;
position: absolute;
z-index: 5;
overflow: hidden;
}
.nivo-box img {
display: block;
}
/* Caption styles */
.nivo-caption {
position: absolute;
left: 0px;
bottom: 0px;
top: 0;
color: #fff;
width: 100%;
height: 100%;
z-index: 8;
padding: 5px 10px;
overflow: hidden;
display: none;
-moz-opacity: 0.8;
filter: alpha(opacity=8);
-webkit-box-sizing: border-box; /* Safari/Chrome, other WebKit */
-moz-box-sizing: border-box;    /* Firefox, other Gecko */
box-sizing: border-box;         /* Opera/IE 8+ */
}
.nivo-caption p {
padding: 14px;
}
.nivo-caption a {
display: inline !important;
}
.nivo-html-caption {
display: none;
}
/* Direction nav styles (e.g. Next & Prev) */
.nivo-directionNav a {
position: absolute;
top: 50%;
z-index: 9;
cursor: pointer;
margin-top: -20px;
}
.nivo-prevNav {
left: 0px;
}
.nivo-nextNav {
right: 0px;
}
/* Control nav styles (e.g. 1,2,3...) */
.nivo-controlNav {
text-align: center;
padding: 15px 0;
}
.nivo-controlNav a {
cursor: pointer;
}
/* ------------------------------
Default Theme
---------------------------------*/
.slider-direction {
position: absolute;
left: 0;
top: 0;
width: 100%;
background: none;
color: #fff;
font-size: 16px;
z-index: 99;
display: none;
}
/* ------------------------------
custom slider css
---------------------------------*/
.slider-progress-bar {
position: absolute;
top: 0;
left: 0;
background-color: #333;
height: 4px;
-webkit-animation: myfirst 5000ms ease-in-out;
-moz-animation: myfirst 5000ms ease-in-out;
-ms-animation: myfirst 5000ms ease-in-out;
animation: myfirst 5000ms ease-in-out;
}
.slider-progress-bar:hover {
-webkit-animation-play-state: paused;
animation-play-state: paused;
}
@-webkit-keyframes myfirst {
from {
width: 0;
}
to {
width: 100%;
}
}
@keyframes myfirst {
from {
width: 0;
}
to {
width: 100%;
}
}
.slider-style-table {
display: table;
height: 100%;
width: 100%;
float: left;
}
.slider-style-table-cell {
display: table-cell;
vertical-align: middle;
}
/* ------------------------------
slider animation
---------------------------------*/
.slider-1 h2 {
-webkit-animation: zoomInUp 500ms ease-in-out;
-moz-animation: zoomInUp 500ms ease-in-out;
-ms-animation: zoomInUp 500ms ease-in-out;
animation: zoomInUp 500ms ease-in-out;
}
.slider-2 h2 {
-webkit-animation: fadeInLeft 500ms ease-in-out;
-moz-animation: fadeInLeft 500ms ease-in-out;
-ms-animation: fadeInLeft 500ms ease-in-out;
animation: fadeInLeft 500ms ease-in-out;
}
.slider-3 h2 {
-webkit-animation: fadeInRight 500ms ease-in-out;
-moz-animation: fadeInRight 500ms ease-in-out;
-ms-animation: fadeInRight 500ms ease-in-out;
animation: fadeInRight 500ms ease-in-out;
}
.desc-layer {
-webkit-animation: fadeInUp 1000ms ease-in-out;
-moz-animation: fadeInUp 1000ms ease-in-out;
-ms-animation: fadeInUp 1000ms ease-in-out;
animation: fadeInUp 1000ms ease-in-out;
}
.sbutton-link {
-webkit-animation: fadeInDown 1500ms ease-in-out;
-moz-animation: fadeInDown 1500ms ease-in-out;
-ms-animation: fadeInDown 1500ms ease-in-out;
animation: fadeInDown 1500ms ease-in-out;
}

